method string_xor(a: seq<char>, b: seq<char>) returns (result: seq<char>)
    requires |a| == |b| // The lengths of the two strings must be equal
    ensures result == (a.Zip(b, (x, y) => if x == y then '0' else '1')) // The result is the XOR of the two input strings
{
    var n := |a|;
    var res := new char[n];

    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant res[..i] == (a[..i].Zip(b[..i], (x, y) => if x == y then '0' else '1'))
    {
        if a[i] == b[i] {
            res[i] := '0';
        } else {
            res[i] := '1';
        }
        i := i + 1;
    }

    result := res;
}

